"""Source classification and streaming regressions using generated bytes only."""
import hashlib
import json
import struct

import pytest

from pmc.sample import _png
from pmc.source import SourceCancelled, scan_source
import pmc.source as source_module


def snapshot(root):
    return {p.relative_to(root).as_posix(): {"size": p.stat().st_size,
            "mtime_ns": p.stat().st_mtime_ns, "sha256": hashlib.sha256(p.read_bytes()).hexdigest()}
            for p in root.rglob("*") if p.is_file()}


def write(root, name, data):
    path = root / name
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(data)
    return path


@pytest.mark.parametrize("name,payload", [("shared_album_comments.json", b"{}"),
    ("Album/SHARED_ALBUM_COMMENTS.JSON", b"\xef\xbb\xbf { \n } \r\n")])
def test_known_empty_comments_are_hashed_inventory_not_comparison_media(tmp_path, name, payload):
    write(tmp_path, name, payload)
    write(tmp_path, "photo.png", _png(10, 20, 30))
    before = snapshot(tmp_path)
    manifest = scan_source(tmp_path)
    assert snapshot(tmp_path) == before
    assert {item["path"] for item in manifest["items"]} == {"photo.png"}
    assert manifest["issues"] == []
    assert len(manifest["inventory"]) == 2
    auxiliary = manifest["auxiliary_files"]
    assert len(auxiliary) == 1
    assert auxiliary[0]["path"] == name
    assert auxiliary[0]["classification"] == "empty_shared_album_comments"
    assert auxiliary[0]["content_state"] == "empty_object"
    assert auxiliary[0]["sha256"] == hashlib.sha256(payload).hexdigest()
    assert auxiliary[0]["sha1"] == hashlib.sha1(payload).hexdigest()
    assert auxiliary[0]["size"] == len(payload)
    inventory = next(entry for entry in manifest["inventory"] if entry["path"] == name)
    assert inventory["sha256"] == auxiliary[0]["sha256"]
    assert manifest["inventory_summary"]["files"] == 2
    assert manifest["inventory_summary"]["media_files"] == 1
    assert manifest["inventory_summary"]["comparison_files"] == 1
    assert manifest["inventory_summary"]["auxiliary_files"] == 1
    assert manifest["inventory_bytes"] == sum(value["size"] for value in before.values())


@pytest.mark.parametrize("name,payload,malformed", [
    ("shared_album_comments.json", b'{"comments": []}', False),
    ("shared_album_comments.json", b'{"comment":"keep me"}', False),
    ("other_empty.json", b"{}", False),
    ("shared_album_comments-copy.json", b"{}", False),
    ("shared_album_comments.json", b"{broken", True),
    ("shared_album_comments.json", b"", True),
    ("shared_album_comments.json", b"[]", True),
    ("shared_album_comments.json", b"null", True),
])
def test_nonempty_unknown_and_malformed_json_stay_explicit(tmp_path, name, payload, malformed):
    write(tmp_path, name, payload)
    before = snapshot(tmp_path)
    manifest = scan_source(tmp_path)
    assert snapshot(tmp_path) == before
    assert manifest["auxiliary_files"] == []
    assert len(manifest["inventory"]) == len(manifest["items"]) == 1
    item = manifest["items"][0]
    assert item["path"] == name and item["supported"] is False
    assert item["sha256"] == hashlib.sha256(payload).hexdigest()
    codes = {issue["code"] for issue in item["issues"]}
    assert "unsupported_format" in codes
    assert ("sidecar_malformed" in codes) is malformed


def test_known_filename_does_not_override_exact_media_sidecar_association(tmp_path):
    # An extensionless but structurally identified image makes this a real
    # exact-file sidecar; auxiliary naming must not take precedence over it.
    write(tmp_path, "shared_album_comments", _png(1, 2, 3))
    write(tmp_path, "shared_album_comments.json", b"{}")
    manifest = scan_source(tmp_path)
    assert manifest["auxiliary_files"] == []
    assert manifest["inventory_summary"]["sidecar_files"] == 1
    assert len(manifest["items"]) == 1
    assert manifest["items"][0]["sidecars"] == ["shared_album_comments.json"]
    assert manifest["items"][0]["sidecar_evidence"] == [{"path": "shared_album_comments.json", "method": "exact_filename"}]


def test_known_filename_does_not_neutralize_conflicting_sidecar_association(tmp_path):
    write(tmp_path, "shared_album_comments", _png(1, 2, 3))
    write(tmp_path, "other.png", _png(3, 2, 1))
    write(tmp_path, "shared_album_comments.json", json.dumps({"title": "other.png", "photoTakenTime": {"timestamp": "123"}}).encode())
    before = snapshot(tmp_path)
    manifest = scan_source(tmp_path)
    assert snapshot(tmp_path) == before
    assert manifest["auxiliary_files"] == []
    assert len(manifest["items"]) == 2
    assert all(not item["sidecars"] and item["capture"] is None for item in manifest["items"])
    assert all(any(issue["code"] == "sidecar_ambiguous" for issue in item["issues"]) for item in manifest["items"])
    assert manifest["inventory_summary"]["sidecar_files"] == 1


def movie(timestamp=1_583_525_797, media_time=None):
    def box(kind, data):
        return struct.pack(">I4s", len(data) + 8, kind) + data
    def date_header(kind, size, value):
        raw = (value + 2_082_844_800).to_bytes(4, "big")
        return box(kind, b"\0" * 4 + raw * 2 + b"\0" * (size - 12))
    handler = box(b"hdlr", b"\0" * 8 + b"vide" + b"\0" * 12)
    description = box(b"stsd", b"\0" * 4 + struct.pack(">I", 1) + box(b"avc1", b"\0" * 78))
    mdia = box(b"mdia", date_header(b"mdhd", 24, timestamp if media_time is None else media_time) + handler + box(b"minf", box(b"stbl", description)))
    moov = box(b"moov", date_header(b"mvhd", 100, timestamp) + box(b"trak", date_header(b"tkhd", 84, timestamp) + mdia))
    return box(b"ftyp", b"isom\0\0\0\0isommp42") + moov + box(b"mdat", b"\1\2\3")


def test_source_hash_stream_retains_separate_container_date_evidence(tmp_path, monkeypatch):
    data = movie()
    write(tmp_path, "video-with-wrong-extension.jpg", data)
    write(tmp_path, "shared_album_comments.json", b"{}")
    monkeypatch.setattr(source_module, "CHUNK_SIZE", 13)
    before = snapshot(tmp_path)
    manifest = scan_source(tmp_path)
    item = manifest["items"][0]
    assert snapshot(tmp_path) == before
    assert item["sha256"] == hashlib.sha256(data).hexdigest()
    assert item["sha1"] == hashlib.sha1(data).hexdigest()
    assert item["media"]["valid"] and item["media"]["family"] == "video"
    evidence = item["media"]["container_creation"]
    assert evidence["valid"] and evidence["complete"]
    assert evidence["timestamp"] == 1_583_525_797
    assert evidence["semantics"] == "container_creation"
    assert evidence["capture_instant_verified"] is False
    assert item["capture"] is None
    assert scan_source(tmp_path)["inventory"] == manifest["inventory"]


def test_invalid_container_date_is_retained_without_promoting_capture(tmp_path):
    data = movie(media_time=1_583_525_799)
    write(tmp_path, "clip.mp4", data)
    item = scan_source(tmp_path)["items"][0]
    assert item["media"]["valid"]
    assert not item["media"]["container_creation"]["valid"]
    assert item["media"]["container_creation"]["timestamp"] is None
    assert item["capture"] is None
    assert item["sha256"] == hashlib.sha256(data).hexdigest()


def test_date_inspector_cancellation_never_returns_partial_manifest(tmp_path, monkeypatch):
    write(tmp_path, "clip.mp4", movie())
    before = snapshot(tmp_path)
    class CancelledDates:
        def __init__(self, **kwargs):
            pass
        def update(self, block):
            raise source_module.MediaCancelled("Controlled cancellation")
    monkeypatch.setattr(source_module, "ContainerDateInspector", CancelledDates)
    with pytest.raises(SourceCancelled):
        scan_source(tmp_path)
    assert snapshot(tmp_path) == before
